<script>
'use strict';const el=id=>document.getElementById(id),safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let index=new Map(),timer=null;
async function request(action,data=null,params={}){const q=new URLSearchParams({action,...params});const res=await fetch('gyd_clientes_api.php?'+q,{method:data?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify({...data,csrf:window.CLI_V36.csrf}):undefined});const j=await res.json();if(!res.ok||j.error)throw Error(j.error||'No se pudo completar la operación');return j;}
async function find(){const q=el('q').value.trim();try{const r=q.length>=2?await request('buscar',null,{q}):await request('recientes');index=new Map((r.clientes||[]).map(x=>[Number(x.id),x]));el('results').innerHTML=r.clientes.length?r.clientes.map(c=>`<button type="button" class="item" data-id="${Number(c.id)}"><span>${safe(c.nombre)}<small>${safe(c.codigo)} · ${safe(c.telefono||'Sin teléfono')}</small></span><span>${Number(c.saldo)||0} puntos</span></button>`).join(''):'Sin coincidencias.';}catch(e){el('feedback').textContent=e.message;}}
async function detail(id){try{const r=await request('ver',null,{id:String(id)});const c=r.cliente;el('details').innerHTML=`<h2>${safe(c.nombre)}</h2><p><b>${safe(c.codigo)}</b> · ${Number(c.activo)?'Activo':'Inactivo'}</p><div class="grid"><div class="kpi">Puntos acumulados<strong>${Number(c.saldo)}</strong></div><div class="kpi">Valor de referencia futuro<strong>$${(Math.max(0,Number(c.saldo))*0.1).toFixed(2)}</strong></div></div><p><span class="tag">Canje no habilitado</span></p><p>Teléfono: ${safe(c.telefono||'Sin registro')}<br>Correo: ${safe(c.correo||'Sin registro')}<br>Consentimiento: ${Number(c.acepta_programa)?'Registrado':'No'}</p><h3>Últimas ventas vinculadas</h3><table><thead><tr><th>Folio</th><th>Fecha</th><th>Estado</th><th>Puntos</th></tr></thead><tbody>${(c.ventas||[]).map(v=>`<tr><td>${safe(v.folio)}</td><td>${safe(v.pagada_en)}</td><td>${safe(v.estado)}</td><td>${v.estado==='PAGADA'?Number(v.puntos_otorgados):'Anulados'}</td></tr>`).join('')||'<tr><td colspan="4">Sin compras vinculadas</td></tr>'}</tbody></table>`+(window.CLI_V36.admin?`<div id="editBox"><h3>Editar información</h3><form id="editForm"><input type="hidden" name="id" value="${Number(c.id)}"><label>Nombre<input name="nombre" maxlength="120" required value="${safe(c.nombre)}"></label><label>Teléfono<input name="telefono" maxlength="22" value="${safe(c.telefono||'')}"></label><label>Correo<input name="correo" type="email" maxlength="190" value="${safe(c.correo||'')}"></label><label><input name="activo" type="checkbox" ${Number(c.activo)?'checked':''}> Cuenta activa</label><button type="submit">Guardar cambios</button></form></div>`:'');const form=el('editForm');if(form)form.onsubmit=async ev=>{ev.preventDefault();const d=new FormData(form);try{await request('editar',{id:Number(d.get('id')),nombre:String(d.get('nombre')),telefono:String(d.get('telefono')),correo:String(d.get('correo')),activo:d.has('activo')?1:0});el('feedback').textContent='Cliente actualizado.';await find();await detail(id);}catch(e){el('feedback').textContent=e.message;}};}catch(e){el('feedback').textContent=e.message;}}
el('q').addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(find,200);});el('refresh').addEventListener('click',find);el('results').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)detail(Number(b.dataset.id));});
find();
el('createForm').onsubmit=async e=>{e.preventDefault();el('feedback').textContent='';const b=e.submitter;b.disabled=true;try{const r=await request('crear',{nombre:el('name').value,telefono:el('phone').value,correo:el('email').value,consentimiento:el('consent').checked});el('createForm').reset();el('q').value=r.cliente.codigo;await find();await detail(Number(r.cliente.id));el('feedback').textContent='Ficha creada correctamente.';}catch(ex){el('feedback').textContent=ex.message;}finally{b.disabled=false;}};
</script></body></html>
